// Runs inside a Web Worker. Loads the WebAssembly build of Haze once, then checks each source
// text it is sent. Haze runs single-threaded here, so a long check blocks only this worker; the
// page stops it by terminating the worker.
// @ts-ignore: haze.mjs is generated by wasm/build.py and loaded at run time
import createHaze from "./haze.mjs";

let haze: any = null;

async function load() {
  if (!haze) {
    haze = await createHaze();
    if (haze._haze_init() !== 0) throw new Error("Haze failed to start");
  }
  return haze;
}

self.onmessage = async (e: MessageEvent) => {
  const { id, src } = e.data;
  try {
    const h = await load();
    const t = performance.now();
    const p = h.stringToNewUTF8(src);
    const out = h._haze_json(p);
    h._free(p);
    const json = h.UTF8ToString(out);
    h._free(out);
    (self as any).postMessage({ id, json, ms: performance.now() - t });
  } catch (err: any) {
    (self as any).postMessage({ id, error: String(err?.message ?? err) });
  }
};

// let the page know the engine is ready, so it can show that before the first check
load().then(
  () => (self as any).postMessage({ ready: true }),
  (err) => (self as any).postMessage({ ready: false, error: String(err?.message ?? err) }),
);
